mapper.select:
select 

from PTL_PORTFOLIO_VALUATION
where CDATE = #{cdate,jdbcType=DATE}
  and PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR}

mapper.delete:
delete from PTL_PORTFOLIO_VALUATION
where CDATE = #{cdate,jdbcType=DATE}
  and PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR}

mapper.update:
update PTL_PORTFOLIO_VALUATION
